using CustomCodeFramework.Core.Pagination;using CustomCodeFramework.Cqrs.Dispatching;using Dhole.Content.Application.ContentItems.GetContentItems;using Dhole.Content.Application.ContentItems.GetPublishedContentBySlug;using Dhole.Content.Application.Navigation.GetNavigationMenu;using Dhole.Content.Application.Settings.GetSiteSettings;using Dhole.Content.Domain.ContentItems.Enums;namespace Dhole.Content.Api.Endpoints;public static class PublicContentEndpoints{public static IEndpointRouteBuilder MapPublicContentEndpoints(this IEndpointRouteBuilder app){var g=app.MapGroup("/api/content/public").WithTags("Public Content").AllowAnonymous();g.MapGet("/content/{slug}",async(string slug,string? siteKey,string? locale,IQueryDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new GetPublishedContentBySlugQuery(siteKey??"main",slug,locale),ct),h));g.MapGet("/content",async(int? pageNumber,int? pageSize,string? siteKey,string? type,string? search,string? locale,IQueryDispatcher d,CancellationToken ct)=>{ContentType? t=Enum.TryParse<ContentType>(type,true,out var tv)?tv:null;var result=await d.DispatchAsync(new GetContentItemsQuery(PageRequest.Create(pageNumber??1,pageSize??20),siteKey??"main",t,ContentStatus.Published,search,locale),ct);return EndpointResults.FromPaged(result);});g.MapGet("/pages/{slug}",async(string slug,string? siteKey,string? locale,IQueryDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new GetPublishedContentBySlugQuery(siteKey??"main",slug,locale),ct),h));g.MapGet("/menus/{location}",async(string location,string? siteKey,IQueryDispatcher d,HttpContext h,CancellationToken ct)=>EndpointResults.FromResult(await d.DispatchAsync(new GetNavigationMenuQuery(siteKey??"main",location),ct),h));g.MapGet("/settings",async(string? siteKey,IQueryDispatcher d,CancellationToken ct)=>EndpointResults.Ok(await d.DispatchAsync(new GetSiteSettingsQuery(siteKey??"main",true),ct)));return app;}}
